Here is the source code:
<source_code>
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

public class Div2_421C {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] inputData = reader.readLine().split(" ");
        int a = Integer.parseInt(inputData[0]);
        int b = Integer.parseInt(inputData[1]);
        int l = Integer.parseInt(inputData[2]);
        int r = Integer.parseInt(inputData[3]);

        // Build initial string: first a letters in alphabetical order
        StringBuilder s = new StringBuilder();
        for (int i = 0; i < a; i++) {
            s.append((char) ('a' + i));
        }

        // Simulate the game
        // Mister B moves first, then opponent, alternating
        // We need to generate enough characters to cover position r

        // Calculate how many full moves we need
        // Initial length is a
        // Each pair of moves (Mister B + opponent) adds (b + a) characters
        // We need to cover up to position r, so we need at least r characters

        int currentLength = a;
        while (currentLength < r) {
            // Mister B's move: append b letters (he can choose optimally to minimize distinct letters)
            // To minimize distinct letters in the final segment, Mister B should append the same letter
            // But we need to consider opponent's response
            // Actually, Mister B wants to minimize distinct letters in [l, r], so he should try to repeat letters
            // However, opponent plays optimally to maximize distinct letters (or at least not cooperate)

            // For Mister B's move: he appends b letters. To minimize distinct letters in the target segment,
            // he should append letters that are already present or will help minimize the count.
            // But since we're looking for the minimum possible number, we assume Mister B plays optimally.

            // The key insight: Mister B can choose any letters, so he can choose to repeat the last letter
            // But opponent's move depends on the last a characters

            // Let's simulate properly:
            // After initial string (length a), Mister B appends b letters (he chooses them)
            // Then opponent appends a letters based on the last a characters

            // To minimize distinct letters in [l, r], Mister B should try to make the string as repetitive as possible
            // The optimal strategy for Mister B is to append the same letter (e.g., 'a') b times
            // But opponent will try to add distinct letters not in the last a characters

            // However, the problem asks for the minimum possible number, so we assume Mister B plays optimally
            // to minimize the distinct count in [l, r]

            // Let's simulate with Mister B choosing optimally
            // Mister B's optimal move: append b copies of the last character (to maximize repetition)
            char lastChar = s.charAt(s.length() - 1);
            for (int i = 0; i < b; i++) {
                s.append(lastChar);
            }

            // Now opponent's move: considers last a characters, finds lexicographically smallest string with distinct letters not in that suffix
            String suffix = s.substring(s.length() - a);
            Set<Integer> usedInSuffix = new HashSet<>();
            for (char c : suffix.toCharArray()) {
                usedInSuffix.add(c - 'a');
            }

            StringBuilder opponentMove = new StringBuilder();
            int letter = 0;
            while (opponentMove.length() < a) {
                if (!usedInSuffix.contains(letter)) {
                    opponentMove.append((char) ('a' + letter));
                    usedInSuffix.add(letter);
                }
                letter++;
            }
            s.append(opponentMove.toString());
        }

        // Now count distinct letters in [l, r] (1-indexed, so convert to 0-indexed: l-1 to r-1)
        Set<Integer> distinct = new HashSet<>();
        for (int i = l - 1; i < r; i++) {
            distinct.add(s.charAt(i) - 'a');
        }
        System.out.println(distinct.size());
    }
}
